@Test
void verifiesFixedBrowserP256ChallengeVector() throws Exception {
    byte[] publicKey = java.util.Base64.getDecoder().decode(
            "MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAESSiXelAglsfsz2LLo8Z+IclqfibAL1f6Zm0cLO3B4towA4Et2eMcMjoXhR8YKdfADmlFLGIy8iE5gRsX25YUMw==");
    byte[] payload = java.util.Base64.getDecoder().decode(
            "amktY3Jvc3MtcnVudGltZS1kZXZpY2UtY2hhbGxlbmdlLXYx");
    byte[] signature = java.util.Base64.getDecoder().decode(
            "MEYCIQCfF3gj4ob1/RaA4yjWFvSGU8w7rTwsc3DcNi1f00tPtQIhAMys4BCFtHcqWFHTNBr017SyaiYFIVZM/uOaXlLZJSwA");
    Signature verifier = Signature.getInstance("SHA256withECDSA");
    verifier.initVerify(java.security.KeyFactory.getInstance("EC").generatePublic(
            new java.security.spec.X509EncodedKeySpec(publicKey)));
    verifier.update(payload);
    assertTrue(verifier.verify(signature));
}

